import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import java.util.Date;
import java.util.Map;

public class JwtService {
    private final String SECRET_KEY = "mySecretKey12345678901234567890";

    public String generateToken(String username) {
        return Jwts.builder()
            .setSubject(username)  // Payload: who this token is for
            .setIssuedAt(new Date())
            .setExpiration(new Date(System.currentTimeMillis() + 86400000))  // 24 hours
            .signWith(SignatureAlgorithm.HS256, SECRET_KEY)  // Header + Signature
            .compact();  // Combines all three parts with dots
    }

    public String extractUsername(String token) {
        return Jwts.parser()
            .setSigningKey(SECRET_KEY)  // Validates signature
            .parseClaimsJws(token)  // Throws exception if tampered
            .getBody()
            .getSubject();  // Extract username from payload
    }
}

import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import java.util.Date;
import java.util.Map;

public class JwtClaimsService {
    private final String SECRET_KEY = "mySecretKey12345678901234567890";

    public String createTokenWithClaims(String userId, String role) {
        var now = new Date();
        var expiryDate = new Date(now.getTime() + 3600000);  // 1 hour

        return Jwts.builder()
            .setSubject(userId)  // Registered: who the token is about
            .setIssuedAt(now)  // Registered: when token was created
            .setExpiration(expiryDate)  // Registered: when token becomes invalid
            .setIssuer("my-auth-service")  // Registered: who issued this token
            .claim("role", role)  // Private: custom claim for authorization
            .claim("tenant_id", "acme-corp")  // Private: multi-tenant identifier
            .signWith(SignatureAlgorithm.HS256, SECRET_KEY)
            .compact();
    }

    public Map<String, Object> extractAllClaims(String token) {
        return Jwts.parser()
            .setSigningKey(SECRET_KEY)
            .parseClaimsJws(token)  // Validates signature and expiration
            .getBody();  // Returns all claims as a map
    }
}

import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import javax.crypto.SecretKey;
import java.util.Date;

public class JwtService {
    private final SecretKey key = Keys.hmacShaKeyFor(
        "your-256-bit-secret-key-here-minimum-32-chars".getBytes()
    );

    public String generateToken(String username) {
        return Jwts.builder()
            .subject(username)  // who the token is for
            .issuedAt(new Date())
            .expiration(new Date(System.currentTimeMillis() + 3600000))  // 1 hour
            .signWith(key)  // HMAC-SHA256 signature
            .compact();
    }

    public String extractUsername(String token) {
        return Jwts.parser()
            .verifyWith(key)  // validates signature
            .build()
            .parseSignedClaims(token)
            .getPayload()
            .getSubject();
    }
}

import jakarta.servlet.FilterChain;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.web.filter.OncePerRequestFilter;

public class JwtAuthenticationFilter extends OncePerRequestFilter {
    private final JwtService jwtService;

    @Override
    protected void doFilterInternal(HttpServletRequest request, 
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws Exception {
        var authHeader = request.getHeader("Authorization");

        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            var token = authHeader.substring(7);  // Remove "Bearer " prefix
            var username = jwtService.extractUsername(token);  // Validates signature

            if (username != null && SecurityContextHolder.getContext().getAuthentication() == null) {
                var authToken = new UsernamePasswordAuthenticationToken(
                    username, null, List.of());  // Populate SecurityContext
                SecurityContextHolder.getContext().setAuthentication(authToken);
            }
        }
        filterChain.doFilter(request, response);  // Continue filter chain
    }
}

